import json
from pathlib import Path
from html import escape as e

ROOT=Path(__file__).parent
OUT=ROOT/'dist'
DATA=json.loads((ROOT/'content.json').read_text())
SCENARIOS=DATA['scenarios']
SUPPORT=json.loads((ROOT/'practice-support.json').read_text())
RELATIONSHIPS=(ROOT/'relationships.json').read_text().replace('<','\\u003c')
PHOTOS=json.loads((ROOT/'photos.json').read_text())
RESOURCES={
 'uhs':{'title':'UHS Sexual Health Care','url':'https://uhs.berkeley.edu/medical/primary-care/sexual-health-care','description':'Information about partner communication, STI testing, contraception, and access to sexual-health care.','use':'When you have a sexual-health question or want to explore care options.','nextStep':'Open the UHS guide and choose Get Tested to compare testing and care options. A clinician can help with individual questions.'},
 'shep':{'title':'Sexual Health Education Program (SHEP)','url':'https://uhs.berkeley.edu/shep','description':'Peer sexual-health education, answers to questions, and safer-sex resources.','use':'When you would like to talk with a trained peer educator.','nextStep':'Use MyUCBerkeleyHealth to schedule a Sexpert Education Clinic appointment, or check the SHEP page for current walk-in hours.'},
 'care':{'title':'PATH to Care: student prevention','url':'https://care.berkeley.edu/prevention-first/undergraduate-student-prevention/','description':'Education on consent, boundaries, and healthy relationships.','use':'When you want to learn more about relationship communication and consent.','nextStep':'Open the student prevention page to explore Consent & Boundaries workshops and the workshop request form for your group.'}
}
def photo(key,classes='',decorative=False,eager=False):
 p=PHOTOS[key]
 alt='' if decorative else p['alt']
 priority='loading="eager" fetchpriority="high"' if eager else 'loading="lazy"'
 return f'<img class="{e(classes)}" data-photo="{e(key)}" src="/assets/{e(p["file"])}" width="{p["width"]}" height="{p["height"]}" alt="{e(alt)}" style="object-position:{e(p["position"])}" {priority} decoding="async">'

def resource_next_step(resource):
 text=e(resource['nextStep'])
 if resource is RESOURCES['shep']:
  text=text.replace('MyUCBerkeleyHealth','<a href="https://myhealth.berkeley.edu/" target="_blank" rel="noopener noreferrer">MyUCBerkeleyHealth</a>')
 return f'<p class="resource-next-step"><strong>Start here:</strong> {text}</p>'

def resource_list(keys):
 return ''.join(f'<li><a href="{e(RESOURCES[k]["url"])}" target="_blank" rel="noopener noreferrer">{e(RESOURCES[k]["title"])}</a><p>{e(RESOURCES[k]["description"])}</p>{resource_next_step(RESOURCES[k])}</li>' for k in keys)
def shell(title,body,current='home',description='Practice conversations about consent, protection, preferences, and sexual health. A student-created educational resource for Berkeley students.'):
 nav=''.join(f'<a href="/{s["slug"]}.html"'+(' aria-current="page"' if current==s['slug'] else '')+f'>{e(s["title"])}</a>' for s in SCENARIOS)
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description)}"><meta name="theme-color" content="#12354a"><title>{e(title)} | Conversation Practice</title><script>try{{const q=new URLSearchParams(location.search).get('style');const t=(q==='academic'||q==='warm')?q:(localStorage.getItem('reading-style')||'warm');document.documentElement.dataset.theme=t;localStorage.setItem('reading-style',t)}}catch(e){{document.documentElement.dataset.theme='warm'}}</script><link rel="stylesheet" href="/assets/style.css"><link rel="stylesheet" href="/assets/style-warm.css"><link rel="stylesheet" href="/assets/story.css"><link rel="stylesheet" href="/assets/levels.css"><link rel="stylesheet" href="/assets/compact.css"><link rel="stylesheet" href="/assets/rewards.css"><link rel="stylesheet" href="/assets/comic.css"><script type="application/json" id="relationship-data">{RELATIONSHIPS}</script><script src="/assets/levels.js" defer></script><script src="/assets/rewards.js" defer></script><script src="/assets/comic.js" defer></script><script src="/assets/story-app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a class="brand" href="/">Conversation<span>Practice</span></a><nav aria-label="Primary"><a href="/#scenarios" {'aria-current="page"' if current=='home' else ''}>Explore scenarios</a><a href="/resources.html" {'aria-current="page"' if current=='resources' else ''}>Resources & sources</a></nav></div></header>
<main id="main" tabindex="-1">{body}</main>
<footer class="site-footer"><div><a class="footer-brand" href="/">Conversation Practice</a><p>A PBHLTH 182 student project · Group 103-3<br>Created for Berkeley students. Independent of the campus services linked here.</p><label class="appearance-label" for="appearance">Appearance</label><select id="appearance"><option value="warm">Warm</option><option value="academic">Academic</option></select></div><div><p>Start where you are. Find your next words.<br>For individual health questions, connect with UHS.</p><a href="/resources.html">Read our sources and project information</a></div></footer>
</body></html>'''

rows=''.join(f'''<a class="scenario-link" href="/{s['slug']}.html#exercise">{photo(s['slug'],'scenario-thumb warm-only',decorative=True)}<div class="scenario-link-copy"><h3>{e(s['title'])}</h3><p>{e(s['tagline'])}</p></div><span class="link-label">Explore the story</span></a>''' for s in SCENARIOS)
home=f'''<section class="home-hero wrap"><div><p class="eyebrow">Sexual health & communication</p><h1>Why is talking about sex so awkward?</h1><p class="lede">Brain rehearsing? Words buffering? Try a conversation, one small step at a time.</p><a class="button primary" href="#scenarios">Choose a conversation</a><p class="quiet">For Berkeley students · At your own pace</p></div><aside class="hero-example academic-only"><p class="eyebrow">An example opening</p><blockquote>“Can we talk about STI testing? I'm nervous bringing it up.”</blockquote><p>Acknowledge the feeling.<br>Name what you want to discuss.</p><a href="/sexual-health.html">Explore this conversation</a></aside><figure class="warm-only hero-illustration hero-photo">{photo('hero',eager=True)}<figcaption>A little practice. More room for understanding. <a href="/resources.html#photo-credits">Photo credits</a></figcaption></figure></section>
<section class="path-section wrap" id="start-path"><div class="path-intro"><p class="eyebrow">Your practice path</p><h2>Make it feel like your conversation.</h2><p>Choose characters and the amount of support you want. You can change both during any story.</p></div><details class="path-settings"><summary>Choose characters & practice support</summary><div class="path-panel" id="practice-path"><noscript><p>Turn on JavaScript to choose a level and try the interactive stories.</p></noscript></div></details></section>
<section class="context-section" id="why-it-feels-awkward"><div class="wrap context-grid"><h2>Why these conversations can feel difficult.</h2><div><p>You may be unsure how to ask, worried about being misunderstood, or used to keeping these topics private. Berkeley UHS recognizes that conversations about sexual health can be challenging.</p><p>Start with the experience that feels familiar. You can choose how much to share and practice at your own pace.</p><a class="text-link" href="/resources.html#evidence">Our evidence and approach</a></div></div>
<div class="wrap barrier-grid"><article><h3>Family &amp; culture</h3><p>You may have learned to keep these topics private. You can start with one need without explaining your whole background. People within the same family or community may feel differently.</p><a href="/preferences.html#exercise">Practice naming a preference</a></article><article><h3>Education &amp; practice</h3><p>Knowing the facts does not always make a first sentence easy. Rehearse an opening, try another, and keep language that feels natural to you.</p><a href="/sexual-health.html#exercise">Try a health conversation</a></article><article><h3>Pressure &amp; fear of judgment</h3><p>You might worry that a question will sound like blame or that a limit will disappoint someone. Naming your needs can help you begin; another person is still responsible for respecting your boundary.</p><a href="/consent-boundaries.html#exercise">Practice stating a boundary</a></article></div></section>
<section class="wrap scenario-section" id="scenarios"><div class="section-intro"><p class="eyebrow">Choose a conversation</p><h2>Start with what's on your mind.</h2><p>Use your chosen characters and level in any of these four six-round stories. Work through an awkward opening, a misunderstanding, and different needs. Your choices shape what happens next.</p></div><div class="scenario-list">{rows}</div></section>
<section class="wrap how-section"><h2>How the practice works.</h2><div class="how-grid"><div><h3>Find your starting point</h3><p>Choose a feeling and a level of support. No typing, score, or perfect answer needed.</p></div><div><h3>Practice</h3><p>Make choices across a six-round story, explore their effects, and revisit a turn to try another route.</p></div><div><h3>Reflect & get support</h3><p>Choose a skill to keep practicing, check in with how you feel, and find relevant Berkeley resources.</p></div></div><p class="privacy-note">Your level and completed stories stay in this browser tab. Clear your path at any time. Your practice selections are not uploaded.</p></section>'''
(OUT/'index.html').write_text(shell('Why is talking about sex so awkward?',home),encoding='utf-8')

for s in SCENARIOS:
 story=json.loads((ROOT/'stories'/f'{s["slug"]}.json').read_text())
 learn=''.join(f'<article><h3>{e(x["heading"])}</h3><p>{e(x["text"])}</p></article>' for x in s['learn'])
 other=''.join(f'<a href="/{q["slug"]}.html#exercise">{e(q["title"])}</a>' for q in SCENARIOS if q['slug']!=s['slug'])
 encoded=json.dumps({'title':s['title'],'slug':s['slug'],'story':story,'support':SUPPORT[s['slug']]},ensure_ascii=False).replace('<','\\u003c')
 body=f'''<div class="wrap scenario-top"><a class="back-link" href="/#scenarios">All conversations</a><p class="eyebrow">Conversation guide</p><h1>{e(s['title'])}</h1><p class="lede">{e(s['intro'])}</p><div class="scenario-actions"><a class="button primary" href="#exercise">Start six-round practice</a><a class="text-link" href="#understand">Read the guide</a></div><nav class="page-nav" aria-label="On this page"><a href="#understand">Understand</a><a href="#exercise">Practice</a><a href="#support">Get support</a></nav></div>
<section class="wrap learning-summary" id="understand"><p class="core-takeaway">{e(s['takeaway'])}</p><details class="learning-details"><summary>Why this topic can feel awkward · Read the guide</summary><div class="learning-grid"><aside><p class="eyebrow">A common concern</p><blockquote>“{e(s['concern'])}”</blockquote><p class="quiet">An example of a question you might have.</p></aside><div class="learn-copy">{learn}<p class="practice-concept"><strong>Skill to notice:</strong> {e(s["courseConcept"])}</p><p class="inline-source"><a href="/resources.html#course-learning">How this practice uses PBHLTH 182 learning</a> · <a href="/resources.html#campus-resources">Berkeley support resources</a></p></div></div></details></section>
<section class="practice-band" id="practice"><div class="wrap practice-layout"><div class="practice-intro"><p class="eyebrow">Practice the conversation</p><h2>{e(story['title'])}</h2><p class="practice-short-note">Six rounds. Two replies at a time. Pause or revisit any turn.</p><figure class="story-art warm-only">{photo(s['slug'])}</figure><p class="practice-cast" id="practice-cast"></p><details class="story-about"><summary>About this story</summary><p class="story-subtitle">{e(story['subtitle'])}</p><p data-story-setting>{e(story['setting'])}</p><p class="story-intro-note">Your homepage settings carry over here. Explore six rounds and a few tiny side quests. Change levels, revisit a choice, or pause at any time. No typing required.</p></details></div><div class="exercise" id="exercise"><noscript><p>This practice needs JavaScript. The explanations and support links remain available without it.</p></noscript></div></div></section>
<section class="wrap support-section" id="support"><h2>Find your next step.</h2><p>Existing Berkeley resources for information, learning, and support.</p><ul class="resource-list">{resource_list(s['resourceKeys'])}</ul></section>
<section class="wrap next-section"><h2>Explore another conversation</h2><nav aria-label="Other scenarios">{other}</nav></section><script type="application/json" id="scenario-data">{encoded}</script>'''
 (OUT/f'{s["slug"]}.html').write_text(shell(s['title'],body,s['slug'],s['intro']),encoding='utf-8')

resource_rows=''.join(f'<article class="resource-detail"><h3><a href="{e(r["url"])}" target="_blank" rel="noopener noreferrer">{e(r["title"])}</a></h3><p>{e(r["description"])}</p><p class="quiet">{e(r["use"])}</p>{resource_next_step(r)}</article>' for r in RESOURCES.values())
course_learning='''<section class="wrap course-learning readable" id="course-learning"><p class="eyebrow">From class to conversation</p><h2>What we apply from PBHLTH 182.</h2><p>Learning objective K asks us to examine communication in romantic and sexual relationships, including conflict and culture. These stories turn that learning into choices you can try and revisit.</p><div class="course-examples"><article><h3>Speak from your own experience</h3><p>DIS 103 Meeting #6 introduced “I” statements and questions that invite a partner's perspective. In <a href="/preferences.html#exercise">Sexual preferences</a>, compare a statement about your own comfort with wording that can sound like criticism.</p></article><article><h3>Check understanding and leave room to pause</h3><p>Meeting #6 also emphasized paraphrasing, clear boundaries, and future check-ins. In <a href="/protection.html#exercise">Protection</a>, clarify what an agreement includes. In <a href="/consent-boundaries.html#exercise">Consent &amp; boundaries</a>, practice changing your mind without promising a later activity.</p></article><article><h3>Connect a health conversation to support</h3><p>Meeting #8 connected STI prevention with partner communication and testing resources. In <a href="/sexual-health.html#exercise">Sexual health</a>, ask about testing without treating the question as an accusation, then find a campus service for individual questions.</p></article></div><p class="inline-source">Course sources: PBHLTH 182, Fall 2026, <a href="https://bcourses.berkeley.edu/courses/1555819/files?preview=95420021" target="_blank" rel="noopener noreferrer">syllabus, learning objective K</a>; DIS 103 (Melody), <a href="https://bcourses.berkeley.edu/courses/1555819/files?preview=95726757" target="_blank" rel="noopener noreferrer">Meeting #6</a> and <a href="https://bcourses.berkeley.edu/courses/1555819/files?preview=95919686" target="_blank" rel="noopener noreferrer">Meeting #8</a>. Course files require bCourses access. The guides and practice on this website are open to everyone.</p></section>'''
photo_credits=''.join(f'<li><a href="{e(p["source"])}" target="_blank" rel="noopener noreferrer">Photo by {e(p["photographer"])} on {e(p["provider"])}</a></li>' for p in PHOTOS.values())
resources=f'''<section class="wrap resource-top"><p class="eyebrow">Information & support</p><h1>Resources you can return to.</h1><p class="lede">Practice can help you find words. These Berkeley resources offer information, education, and support beyond an example conversation.</p></section>
<section class="wrap resource-details" id="campus-resources"><h2>Berkeley campus resources</h2>{resource_rows}<p class="quiet">Check each service's page for current availability and appointment details.</p></section>
{course_learning}
<section class="evidence-section" id="evidence"><div class="wrap readable"><p class="eyebrow">Our evidence and approach</p><h2>Research informing the practice.</h2><p>Berkeley UHS identifies sexual history, STI testing, protection, boundaries, and preferences as important topics for partner communication, and recognizes that these discussions can be challenging.</p><p>A survey of 1,349 college students across six US universities found that confidence, communication expectations, and perceived partner attitudes were associated with safer-sex communication. This observational study does not establish cause and effect or estimate how common a concern is among Berkeley students.</p><p class="citation">DiIorio, C., Dudley, W. N., Lehr, S., & Soet, J. E. (2000). <a href="https://doi.org/10.1046/j.1365-2648.2000.01525.x" target="_blank" rel="noopener noreferrer">Correlates of safer sex communication among college students</a>. <em>Journal of Advanced Nursing, 32</em>(3), 658–665. <a href="https://pubmed.ncbi.nlm.nih.gov/11012809/" target="_blank" rel="noopener noreferrer">Research abstract</a>.</p><p>Research with young adults also highlights a need for practical scripts, conversation examples, and accessible education about sexual health and relationships. This informs our use of guided stories; it is not an evaluation of this website.</p><p class="citation">Gilbert, S., Rogers, J., Carmody, M., &amp; McGovern, L. (2026; first published online 2025). <a href="https://doi.org/10.1080/15546128.2025.2459381" target="_blank" rel="noopener noreferrer">Uncovering What Matters to Young Adults: Communicating About Sexual Health &amp; Relationships</a>. <em>American Journal of Sexuality Education, 21</em>(3), 279–301.</p><p>These research samples are not Berkeley-specific. Berkeley UHS, SHEP, and PATH to Care are campus information and support resources, distinct from the research cited above.</p><h3>How we use that context</h3><p>Our original contribution is a self-paced set of branching conversations, with adjustable coaching and opportunities to try another response. These four stories complement existing campus information and peer education by giving Berkeley students a place to rehearse wording, respond to misunderstandings, and navigate different needs. You can adapt the language to your own voice while respecting each person's boundaries and choices.</p><p>The intended benefit is clearer language and a useful next step. The project's effect on confidence or sexual-health behavior has not been established. A small usability test can help us improve wording and navigation; it cannot by itself demonstrate a health outcome.</p><p>The opening check-in suggests a level of guidance for practice. It is a personal reflection, not a validated assessment of communication skill. Before-and-after feelings are shown only to the person practicing and do not establish that the project caused a change.</p><h3 id="photo-credits">Photography &amp; illustration credits</h3><p>Editorial photographs show everyday conversations. Pictured people are not project participants or the named story characters, and no health status is implied. Locations shown are not presented as Berkeley.</p><ul class="photo-credits">{photo_credits}</ul><p>Photographs are used under the <a href="https://www.pexels.com/license/" target="_blank" rel="noopener noreferrer">Pexels License</a>. The interactive stories use AI-generated comic characters to show different conversation moments.</p><h3>About this project</h3><p>Created for PBHLTH 182, discussion group 103-3, by Wenqi Zhang, Xuanyu Lin, Zijian Huang, and Yanghong Liu. The STI-testing example and four-topic structure build on our group proposal and pitch.</p><p>UHS, SHEP, and PATH to Care are existing campus resources. Linking to them does not imply a partnership or endorsement. Campus resource pages and the Gilbert et al. citation were rechecked November 25, 2026. Other research citations were checked November 19, 2026.</p><h3>AI assistance</h3><p>AI tools assisted with website code, wording drafts, and comic illustrations. This use was permitted for the project by the teaching team. The sources above identify the course and research material informing the educational content.</p><p class="privacy-note">Your practice characters, starting check-in, chosen level, and completed topics are saved for this tab. Use “Clear my practice path” on the home page to remove them. Story choices, side-quest selections, and the closing check-in reset on reload. These selections are not uploaded.</p></div></section>'''
(OUT/'resources.html').write_text(shell('Resources & sources',resources,'resources'),encoding='utf-8')
print(f'Generated {len(SCENARIOS)+2} complete pages.')
